 private int checkpointId,materialId,stopTimeSeconds,correctOption; private String questionPrompt,optionA,optionB,optionC,optionD,explanation;
 public int getCheckpointId(){return checkpointId;} public void setCheckpointId(int v){checkpointId=v;} public int getMaterialId(){return materialId;} public void setMaterialId(int v){materialId=v;} public int getStopTimeSeconds(){return stopTimeSeconds;} public void setStopTimeSeconds(int v){stopTimeSeconds=v;} public int getCorrectOption(){return correctOption;} public void setCorrectOption(int v){correctOption=v;} public String getQuestionPrompt(){return questionPrompt;} public void setQuestionPrompt(String v){questionPrompt=v;} public String getOptionA(){return optionA;} public void setOptionA(String v){optionA=v;} public String getOptionB(){return optionB;} public void setOptionB(String v){optionB=v;} public String getOptionC(){return optionC;} public void setOptionC(String v){optionC=v;} public String getOptionD(){return optionD;} public void setOptionD(String v){optionD=v;} public String getExplanation(){return explanation;} public void setExplanation(String v){explanation=v;}
